// Build the installed, import-free selection module from its maintained owners.
// Run: node scripts/build-test-entry-rules.mjs
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { rolldown } from "rolldown";

const root = new URL("../", import.meta.url);
const scripts = new URL("src/skills/dough-execute-plan/scripts/", root);
// Prefix after minification: ordinary output.banner comments can be stripped.
const provenance =
  "// Generated by node scripts/build-test-entry-rules.mjs. Do not edit.\n// Bundles the shared declaration/membership owners and minimatch; licenses: test-entry-rules-LICENSE.txt.\n";
async function retain(name, content) {
  const target = new URL(name, scripts);
  if (process.argv.includes("--check")) {
    if ((await readFile(target, "utf8")) !== content) {
      throw new Error(
        `Regenerate ${name}: node scripts/build-test-entry-rules.mjs`,
      );
    }
  } else {
    await writeFile(target, content);
  }
}
const bundle = await rolldown({
  input: fileURLToPath(new URL("test-entry-rules-selection.mjs", scripts)),
  platform: "neutral",
});
try {
  const { output } = await bundle.generate({
    format: "esm",
    minify: true,
  });
  if (
    output.length !== 1 ||
    output[0].type !== "chunk" ||
    output[0].imports.length
  ) {
    throw new Error("Test-entry selection must be one import-free module");
  }
  await retain("test-entry-rules-runtime.mjs", provenance + output[0].code);
  // The membership owner imports this generated matcher snapshot. Its notices
  // describe the same bundled bytes; dependency discovery stays with its build.
  const notices = await readFile(
    new URL("src/skills/dough-makeme/scripts/minimatch.LICENSE.md", root),
    "utf8",
  );
  await retain("test-entry-rules-LICENSE.txt", notices);
} finally {
  await bundle.close();
}
